  Map<String,Object>reviewCandidate,reviewHistoryItem; synchronized(this){deadlineCheck();if(failed||reviewDone&&reviewStatus.equals("FAILED"))return;reviewCandidate=status(s.binding);reviewCandidate.put("reviewSHA256",result);reviewCandidate.put("reviewStatus","DURABLE");reviewHistoryItem=new LinkedHashMap<>(history.get(s.binding.contextSHA256));reviewHistoryItem.put("reviewStatus","DURABLE");reviewHistoryItem.put("reviewSHA256",result);List<Object>candidateHistory=new ArrayList<>();for(Map.Entry<String,Map<String,Object>>entry:history.entrySet())candidateHistory.add(entry.getKey().equals(s.binding.contextSHA256)?reviewHistoryItem:entry.getValue());reviewCandidate.put("history",candidateHistory);}
  verifyReview(new JSONObject(Values.json(reviewHistoryItem)),new JSONObject(new String(s.bytes,StandardCharsets.UTF_8)));
